    /**
     * Handles loading a User using a UUID
     * @param		UUID uuid 
     * @return		User
     */    
    @GetMapping("/load")
    public User load( @RequestParam(required=true) UUID uuid ) {    	
    	User entity = null;

    	try {  
    		entity = service.getUser( new UserFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load User using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all User business objects
     * @return		Set<User>
     */
    @GetMapping("/")
    public List<User> loadAll() {                
    	List<User> userList = null;
        
    	try {
            // load the User
            userList = service.getAllUser();
            
            if ( userList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Users" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Users ", exc );
        	return null;
        }

        return userList;
                            
    }

